import { create } from 'zustand';
import { createJSONStorage, persist } from 'zustand/middleware';
import AsyncStorage from '@react-native-async-storage/async-storage';

/**
 * PERMISSION TO SEND PERSONAL DATA TO THIRD-PARTY AI (App Review 5.1.1(i) / 5.1.2(i), 2026-11-04).
 *
 * Everything a counselor says is generated by Google (Gemini) or OpenAI from what the person gives
 * the app — questions, voice, birth details, diary text. Apple requires the app itself (not only the
 * privacy policy) to say what is sent and to whom, and to ask BEFORE anything is sent. The gate in
 * RootNavigator holds every signed-in screen behind AiConsentScreen until this store says yes for
 * the account that is signed in.
 *
 * Per account, not per device: a second account on the same phone has not agreed to anything. The
 * row survives sign-out (`prayers.aiConsent` is in forgetLocalData's KEEP list) so the same person
 * signing back in is not asked again, and deleting the account drops that account's entry.
 *
 * VERSIONED: when what is sent or who receives it changes, bump AI_CONSENT_VERSION and every account
 * is asked again — a yes to the old list is not a yes to the new one.
 */
export const AI_CONSENT_VERSION = 1;

interface Grant {
  version: number;
  /** ms since epoch, when the person tapped "agree". */
  at: number;
}

interface AiConsentState {
  byUid: Record<string, Grant>;
}

export const useAiConsent = create<AiConsentState>()(
  persist(() => ({ byUid: {} }) as AiConsentState, {
    name: 'prayers.aiConsent',
    storage: createJSONStorage(() => AsyncStorage),
  }),
);

/**
 * False until AsyncStorage has been read — the gate must not decide before it knows. Kept OUT of
 * the persisted store: setting it there from onRehydrateStorage would write the row straight back.
 */
const useLoaded = create<{ loaded: boolean }>(() => ({ loaded: false }));
{
  const p = (useAiConsent as unknown as { persist?: { hasHydrated(): boolean; onFinishHydration(cb: () => void): () => void } }).persist;
  if (!p || p.hasHydrated()) useLoaded.setState({ loaded: true });
  else p.onFinishHydration(() => useLoaded.setState({ loaded: true }));
}

export function hasAiConsent(uid: string | null | undefined, state: AiConsentState = useAiConsent.getState()) {
  if (!uid) return false;
  const g = state.byUid[uid];
  return g != null && g.version >= AI_CONSENT_VERSION;
}

/** The hook the gate reads: null while the stored answer is still loading. */
export function useAiConsentFor(uid: string | null | undefined): boolean | null {
  const loaded = useLoaded(s => s.loaded);
  const yes = useAiConsent(s => hasAiConsent(uid, s));
  return loaded ? yes : null;
}

export function grantAiConsent(uid: string, now = Date.now()) {
  useAiConsent.setState(s => ({ byUid: { ...s.byUid, [uid]: { version: AI_CONSENT_VERSION, at: now } } }));
}

export function withdrawAiConsent(uid: string) {
  useAiConsent.setState(s => {
    const { [uid]: _gone, ...rest } = s.byUid;
    return { byUid: rest };
  });
}

export function aiConsentGrantedAt(uid: string | null | undefined): number | null {
  if (!uid) return null;
  return useAiConsent.getState().byUid[uid]?.at ?? null;
}
